#include <iostream>
#include <memory>
struct Res { Res(){ std::cout << "open\n"; } ~Res(){ std::cout << "dtor\n"; } };
void my_delete(Res* r) { std::cout << "custom delete\n"; delete r; }   // 删除器类型被擦除
int main() {
    std::shared_ptr<Res> p(new Res(), my_delete);   // 无论删除器类型，p 的类型都是 shared_ptr<Res>
    std::cout << "ok\n";
}                                       // 析构时调用 my_delete → custom delete → dtor
